    <style>
        :root{--green:#18c47b;--deep:#111827;--panel:#17233d;--card:#1c3154}*{box-sizing:border-box}body{margin:0;overflow:hidden;background:var(--deep);color:#fff;font-family:Inter,ui-sans-serif,system-ui}.pos{display:flex;height:100vh}.catalog{display:flex;min-width:0;flex:1;flex-direction:column;background:linear-gradient(145deg,#16213e,#101827)}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff15;background:linear-gradient(100deg,#10b981,#0ea569);padding:12px 20px}.brand{display:flex;align-items:center;gap:10px}.brand-icon{display:grid;height:38px;width:38px;place-items:center;border-radius:12px;background:#ffffff25;font-size:22px}.brand b{display:block;font-size:16px}.brand small{font-size:11px;opacity:.85}.top-right{display:flex;align-items:center;gap:10px;font-size:12px}.top-right .user{border-radius:999px;background:#ffffff20;padding:7px 12px}.back{border:1px solid #fff7;border-radius:9px;padding:7px 10px;color:#fff;text-decoration:none}.tools{display:flex;gap:10px;border-bottom:1px solid #ffffff10;background:#111827;padding:12px 16px}.search{min-width:0;flex:1;border:1px solid #ffffff10;border-radius:10px;background:#17233d;padding:11px 14px;color:#fff;outline:0}.search:focus{border-color:var(--green);box-shadow:0 0 0 3px #18c47b20}.categories{display:flex;gap:8px;overflow:auto;padding:10px 16px 2px}.category{white-space:nowrap;border:1px solid #ffffff15;border-radius:999px;background:#17233d;padding:7px 13px;color:#aeb9c9;font-size:12px;cursor:pointer}.category.active{border-color:var(--green);background:var(--green);color:#062519;font-weight:800}.products{display:grid;flex:1;grid-template-columns:repeat(auto-fill,minmax(165px,1fr));gap:12px;overflow:auto;padding:14px 16px 24px}.product{position:relative;border:1px solid #ffffff0d;border-radius:15px;background:linear-gradient(145deg,#203b64,#172b4b);padding:12px;color:#fff;text-align:left;cursor:pointer;transition:.18s}.product:hover{transform:translateY(-2px);border-color:#18c47b80;box-shadow:0 12px 24px #0003}.product .icon{display:grid;height:52px;place-items:center;border-radius:11px;background:#ffffff08;font-size:30px}.product .name{display:block;margin-top:9px;height:33px;overflow:hidden;font-size:13px;font-weight:700;line-height:1.3}.product .unit{display:inline-block;margin-top:5px;border-radius:6px;background:#ffffff14;padding:3px 6px;color:#a9f3ce;font-size:10px;font-weight:800}.product .bottom{display:flex;align-items:end;justify-content:space-between;margin-top:10px}.product .price{color:#55e3a5;font-size:14px;font-weight:900}.product .stock{font-size:10px;color:#c5cfdb}.product .stock.low{color:#fbbf24}.cart{display:flex;width:400px;flex-direction:column;border-left:1px solid #ffffff12;background:#0f3460}.customer{display:flex;align-items:center;gap:10px;background:linear-gradient(100deg,#10b981,#0ea569);padding:13px 16px}.avatar{display:grid;height:34px;width:34px;place-items:center;border-radius:50%;background:#fff3}.customer label{display:block;font-size:10px;opacity:.8}.customer input{width:100%;border:0;background:transparent;color:#fff;font-size:14px;font-weight:800;outline:0}.cart-head{display:flex;align-items:center;justify-content:space-between;background:#111827;padding:12px 16px}.cart-head h2{margin:0;font-size:15px}.clear-cart{border:0;border-radius:7px;background:#ef5350;color:#fff;padding:6px 9px;font-size:11px;font-weight:800;cursor:pointer}.cart-list{flex:1;overflow:auto;padding:10px}.cart-empty{padding:65px 15px;text-align:center;color:#8d9aae}.line{display:flex;align-items:center;gap:8px;border-bottom:1px solid #ffffff12;padding:11px 4px}.line-info{min-width:0;flex:1}.line-info b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:12px}.line-info small{display:block;margin-top:4px;color:#aab6c7;font-size:10px}.qty{display:flex;align-items:center;gap:4px}.qty button{height:24px;width:24px;border:0;border-radius:6px;background:#234c78;color:#fff;font-weight:900;cursor:pointer}.qty span{width:22px;text-align:center;font-size:12px}.line-total{font-size:12px;font-weight:900}.remove{border:0;background:none;color:#ff7373;cursor:pointer}.summary{border-top:1px solid #ffffff18;background:#16213e;padding:13px 16px}.summary-row{display:flex;justify-content:space-between;margin:6px 0;color:#bac5d4;font-size:12px}.summary-row.total{margin-top:10px;color:#fff;font-size:20px;font-weight:900}.summary-row.total b{color:#58e6a7}.pay{border:0;background:var(--green);padding:17px;color:#062519;font-size:16px;font-weight:950;cursor:pointer}.pay:disabled{cursor:not-allowed;opacity:.45}.modal{position:fixed;inset:0;z-index:20;display:none;place-items:center;background:#020617c9;padding:15px}.modal.open{display:grid}.dialog{width:min(470px,100%);border:1px solid #ffffff18;border-radius:18px;background:#17233d;padding:22px;box-shadow:0 24px 80px #0008}.dialog h2{margin:0 0 18px;font-size:19px}.methods{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.method{border:1px solid #ffffff18;border-radius:10px;background:#0f3460;padding:11px;color:#fff;cursor:pointer}.method.active{border-color:var(--green);background:var(--green);color:#062519;font-weight:900}.field{margin-top:14px}.field label{display:block;margin-bottom:6px;color:#b9c4d2;font-size:12px}.field input{width:100%;border:1px solid #ffffff12;border-radius:9px;background:#0f3460;padding:11px;color:#fff;outline:0}.quick{display:flex;gap:6px;margin-top:8px}.quick button{flex:1;border:1px solid #ffffff14;border-radius:8px;background:#203b64;padding:7px;color:#cbd5e1;font-size:11px;cursor:pointer}.totals{margin-top:16px;border-top:1px solid #ffffff18;padding-top:12px}.totals div{display:flex;justify-content:space-between;margin:7px 0;font-size:13px}.totals .grand{font-size:19px;font-weight:900}.actions{display:flex;justify-content:flex-end;gap:8px;margin-top:20px}.cancel,.checkout{border:0;border-radius:9px;padding:11px 15px;color:#fff;font-weight:900;cursor:pointer}.cancel{background:#ef5350}.checkout{background:var(--green);color:#062519}.shortcuts{padding:7px 15px;background:#0b1220;color:#718096;font-size:10px;text-align:center}@media(max-width:850px){body{overflow:auto}.pos{height:auto;min-height:100vh;flex-direction:column}.catalog{min-height:58vh}.cart{width:auto;min-height:42vh}.top{padding:10px 12px}.top-right .user{display:none}.products{grid-template-columns:repeat(2,1fr)}}
        @media(max-width:520px){.top{align-items:flex-start;gap:8px}.brand-icon{height:32px;width:32px;font-size:17px}.brand b{font-size:14px}.brand small{font-size:10px}.top-right{gap:6px}.top-right #clock{display:none}.back{padding:6px 8px;font-size:11px}.tools{padding:10px 12px}.categories{padding-inline:12px}.products{gap:9px;padding:12px;grid-template-columns:repeat(2,minmax(0,1fr))}.product{padding:10px}.product .icon{height:42px;font-size:24px}.product .price{font-size:12px}.product .bottom{align-items:flex-start;flex-direction:column;gap:3px}.cart{min-height:unset}.cart-list{max-height:45vh}.summary{padding:12px}.summary-row.total{font-size:18px}.dialog{padding:16px}.methods{gap:6px}.method{padding:9px 5px;font-size:11px}.quick{flex-wrap:wrap}.quick button{min-width:30%}.actions{justify-content:stretch}.cancel,.checkout{flex:1;padding:11px 8px}}
    </style>
</head>
<body>
<form id="sale-form" method="POST" action="{{ route('sales.store') }}">@csrf</form>
<div class="pos">
    <section class="catalog">
        <header class="top"><div class="brand"><span class="brand-icon">🌿</span><span><b>POS Jamu</b><small>{{ auth()->user()->isWarehouse() ? 'Penjualan Gudang' : 'Kasir Penjualan' }} · {{ app(\App\Services\StoreContext::class)->store()->name }}</small></span></div><div class="top-right"><span id="clock"></span><span class="user">{{ auth()->user()->name }}</span><a href="{{ route('dashboard') }}" class="back">← Dashboard</a></div></header>
        <div class="tools"><input id="search" class="search" autofocus placeholder="Cari nama, kode, atau scan barcode..."><button type="button" id="scan-barcode" class="back" title="Scan barcode dari kamera">Scan</button></div>
        <div class="categories" id="categories"><button type="button" class="category active" data-category="all">Semua Produk</button>@foreach($products->pluck('category')->filter()->unique('id') as $category)<button type="button" class="category" data-category="{{ $category->id }}">{{ $category->name }}</button>@endforeach</div>
        <main class="products" id="products">
            @forelse($products as $product)
                @php($baseAvailable = $product->stock)
                <button type="button" class="product" data-key="{{ $product->id }}-base" data-id="{{ $product->id }}" data-name="{{ $product->name }}" data-code="{{ $product->code }}" data-barcode="{{ $product->barcode }}" data-price="{{ $product->price }}" data-stock="{{ $baseAvailable }}" data-unit="{{ $product->unit }}" data-conversion="1" data-category="{{ $product->category_id }}"><span class="icon">🌿</span><span class="name">{{ $product->name }}</span><span class="unit">{{ $product->unit }}</span><span class="bottom"><span class="price">Rp {{ number_format($product->price,0,',','.') }}</span><span class="stock {{ $baseAvailable <= $product->minimum_stock ? 'low' : '' }}">{{ $baseAvailable }} {{ $product->unit }}</span></span></button>
                @foreach($product->packagings as $packaging)
                    @php($available = intdiv((int) $product->stock, (int) $packaging->conversion_quantity))
                    <button type="button" class="product" data-key="{{ $product->id }}-{{ $packaging->id }}" data-id="{{ $product->id }}" data-packaging-id="{{ $packaging->id }}" data-name="{{ $product->name }}" data-code="{{ $product->code }}" data-barcode="" data-price="{{ $packaging->price }}" data-stock="{{ $available }}" data-unit="{{ $packaging->name }}" data-conversion="{{ $packaging->conversion_quantity }}" data-category="{{ $product->category_id }}"><span class="icon">📦</span><span class="name">{{ $product->name }}</span><span class="unit">{{ $packaging->name }} = {{ $packaging->conversion_quantity }} {{ $product->unit }}</span><span class="bottom"><span class="price">Rp {{ number_format($packaging->price,0,',','.') }}</span><span class="stock {{ $available <= 0 ? 'low' : '' }}">{{ $available }} {{ $packaging->name }}</span></span></button>
                @endforeach
            @empty
                <div class="cart-empty">Belum ada produk aktif.</div>
            @endforelse
        </main>
        <div class="shortcuts">F2 Cari · F4 Bayar · F8 Kosongkan keranjang · Karton otomatis mengurangi stok sesuai isi</div>
    </section>
    <aside class="cart">
        <div class="customer"><span class="avatar">👤</span><div style="flex:1"><label>Customer</label><input id="customer" placeholder="Umum"></div></div>
        <div class="cart-head"><h2>🛒 Keranjang <span id="count" style="color:#7ee8b8;font-size:11px">0 item</span></h2><button type="button" class="clear-cart" id="clear-cart">Kosongkan</button></div>
        <div id="cart-list" class="cart-list"><div class="cart-empty"><div style="font-size:42px">🛒</div><p>Keranjang masih kosong</p><small>Pilih produk untuk memulai transaksi</small></div></div>
        <div class="summary"><div class="summary-row"><span>Subtotal</span><b id="subtotal">Rp 0</b></div><div class="summary-row"><span>Diskon</span><b id="discount-label">Rp 0</b></div><div class="summary-row total"><span>Total</span><b id="total">Rp 0</b></div></div>
        <button class="pay" type="button" id="pay" disabled>💳 BAYAR <span style="font-size:11px">(F4)</span></button>
    </aside>
</div>
<div class="modal" id="modal"><div class="dialog"><h2>🧾 Pembayaran <small style="color:#8eeac0;font-size:13px">· <span id="modal-customer">Umum</span></small></h2><div class="methods"><button type="button" class="method active" data-method="cash">💵 Tunai</button><button type="button" class="method" data-method="qris">▣ QRIS</button><button type="button" class="method" data-method="transfer">⇄ Transfer</button></div><div class="field"><label>Diskon</label><input id="discount" type="number" min="0" value="0"></div><div class="field"><label>Jumlah pembayaran</label><input id="paid" type="number" min="0" placeholder="Masukkan nominal" autofocus><div class="quick"><button type="button" data-quick="exact">Uang pas</button><button type="button" data-quick="10000">Rp10.000</button><button type="button" data-quick="50000">Rp50.000</button></div></div><div class="totals"><div><span>Subtotal</span><b id="m-subtotal">Rp 0</b></div><div><span>Diskon</span><b id="m-discount">Rp 0</b></div><div class="grand"><span>Total</span><b id="m-total">Rp 0</b></div><div><span>Kembalian</span><b id="change">Rp 0</b></div></div><div class="actions"><button type="button" class="cancel" id="cancel">Batal</button><button type="button" class="checkout" id="checkout">✅ Checkout</button></div></div></div>
<div class="modal" id="scanner-modal"><div class="dialog"><h2>Scan barcode</h2><p style="color:#b9c4d2;font-size:12px">Arahkan kamera ke barcode produk. Izin kamera diperlukan.</p><video id="scanner-video" autoplay playsinline style="width:100%;border-radius:12px;background:#0b1220"></video><p id="scanner-status" style="color:#8eeac0;font-size:12px"></p><div class="actions"><button type="button" class="cancel" id="scanner-close">Tutup</button></div></div></div>
<script>
let cart=[],method='cash',submitting=false;
const money=n=>'Rp '+new Intl.NumberFormat('id-ID').format(n||0),$=id=>document.getElementById(id),subtotal=()=>cart.reduce((sum,item)=>sum+item.price*item.qty,0),grand=()=>Math.max(0,subtotal()-(+$('discount').value||0));
function render(){const count=cart.reduce((sum,item)=>sum+item.qty,0);$('count').textContent=count+' item';$('cart-list').innerHTML=cart.length?cart.map(item=>`<div class="line"><div class="qty"><button type="button" data-minus="${item.key}">−</button><span>${item.qty}</span><button type="button" data-plus="${item.key}">+</button></div><div class="line-info"><b>${item.name}</b><small>${item.unit} · ${money(item.price)} × ${item.qty}</small></div><span class="line-total">${money(item.price*item.qty)}</span><button type="button" class="remove" data-remove="${item.key}">×</button></div>`).join(''):'<div class="cart-empty"><div style="font-size:42px">🛒</div><p>Keranjang masih kosong</p></div>';$('subtotal').textContent=money(subtotal());$('discount-label').textContent=money(+$('discount').value||0);$('total').textContent=money(grand());$('m-subtotal').textContent=money(subtotal());$('m-discount').textContent=money(+$('discount').value||0);$('m-total').textContent=money(grand());$('change').textContent=money(Math.max(0,(+$('paid').value||0)-grand()));$('pay').disabled=!cart.length;document.querySelectorAll('[data-minus]').forEach(button=>button.onclick=()=>adjust(button.dataset.minus,-1));document.querySelectorAll('[data-plus]').forEach(button=>button.onclick=()=>adjust(button.dataset.plus,1));document.querySelectorAll('[data-remove]').forEach(button=>button.onclick=()=>{cart=cart.filter(item=>item.key!==button.dataset.remove);render()})}
function adjust(key,change){const item=cart.find(row=>row.key===key);if(item){item.qty=Math.max(1,Math.min(item.stock,item.qty+change));render()}}
document.querySelectorAll('.product').forEach(card=>card.onclick=()=>{const stock=+card.dataset.stock;if(stock<1){alert('Stok untuk satuan ini tidak tersedia.');return}const item={key:card.dataset.key,id:+card.dataset.id,packagingId:card.dataset.packagingId?+card.dataset.packagingId:null,name:card.dataset.name,price:+card.dataset.price,stock,unit:card.dataset.unit,conversion:+card.dataset.conversion,qty:1};const old=cart.find(row=>row.key===item.key);old?old.qty=Math.min(old.stock,old.qty+1):cart.push(item);render();$('search').focus()});
function filter(){const query=$('search').value.toLowerCase(),category=document.querySelector('.category.active').dataset.category;document.querySelectorAll('.product').forEach(card=>{const matches=(card.dataset.name+' '+card.dataset.code+' '+card.dataset.barcode+' '+card.dataset.unit).toLowerCase().includes(query)&&(category==='all'||card.dataset.category===category);card.style.display=matches?'block':'none'})}$('search').oninput=filter;document.querySelectorAll('.category').forEach(button=>button.onclick=()=>{document.querySelectorAll('.category').forEach(row=>row.classList.remove('active'));button.classList.add('active');filter()});$('clear-cart').onclick=()=>{if(cart.length&&confirm('Kosongkan semua isi keranjang?')){cart=[];render()}};$('pay').onclick=()=>{if(cart.length){$('modal-customer').textContent=$('customer').value||'Umum';$('modal').classList.add('open');$('paid').focus();render()}};$('cancel').onclick=()=>$('modal').classList.remove('open');document.querySelectorAll('.method').forEach(button=>button.onclick=()=>{method=button.dataset.method;document.querySelectorAll('.method').forEach(row=>row.classList.toggle('active',row===button))});$('discount').oninput=$('paid').oninput=render;document.querySelectorAll('[data-quick]').forEach(button=>button.onclick=()=>{$('paid').value=button.dataset.quick==='exact'?grand():button.dataset.quick;render()});
const customerDirectory=@json($customers->map(fn($customer)=>['id'=>$customer->id,'name'=>$customer->name,'code'=>$customer->member_code])->values());const list=document.createElement('datalist');list.id='customer-list';customerDirectory.forEach(customer=>{const option=document.createElement('option');option.value=customer.name;option.label=customer.code;list.appendChild(option)});document.body.appendChild(list);$('customer').setAttribute('list','customer-list');
$('checkout').onclick=()=>{if(submitting)return;if((+$('paid').value||0)<grand()){alert('Jumlah pembayaran kurang dari total.');return}submitting=true;const form=$('sale-form'),customer=customerDirectory.find(row=>row.name.toLowerCase()===$('customer').value.trim().toLowerCase());form.insertAdjacentHTML('beforeend',`<input name="customer_name" value="${$('customer').value}"><input name="customer_id" value="${customer?.id||''}"><input name="discount" value="${$('discount').value||0}"><input name="payment_method" value="${method}"><input name="paid_amount" value="${$('paid').value}">`+cart.map((item,index)=>`<input name="items[${index}][product_id]" value="${item.id}"><input name="items[${index}][product_packaging_id]" value="${item.packagingId||''}"><input name="items[${index}][quantity]" value="${item.qty}">`).join(''));form.submit()};document.addEventListener('keydown',event=>{if(event.key==='F2'){event.preventDefault();$('search').focus()}if(event.key==='F4'){event.preventDefault();if(cart.length)$('pay').click()}if(event.key==='F8'){event.preventDefault();$('clear-cart').click()}if(event.key==='Escape')$('modal').classList.remove('open');if(event.key==='Enter'&&document.activeElement===$('search')){const visible=[...document.querySelectorAll('.product')].find(card=>card.style.display!=='none');if(visible)visible.click()}});setInterval(()=>$('clock').textContent=new Date().toLocaleString('id-ID',{dateStyle:'medium',timeStyle:'short'}),1000);render();
let scannerStream=null,scannerTimer=null;
function stopScanner(){if(scannerTimer)clearInterval(scannerTimer);scannerTimer=null;if(scannerStream)scannerStream.getTracks().forEach(track=>track.stop());scannerStream=null;$('scanner-modal').classList.remove('open')}
async function startScanner(){if(!('BarcodeDetector' in window)||!navigator.mediaDevices?.getUserMedia){alert('Scanner kamera belum didukung browser ini. Gunakan kolom pencarian atau scanner barcode USB.');return}$('scanner-modal').classList.add('open');$('scanner-status').textContent='Menyalakan kamera...';try{scannerStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'}},audio:false});$('scanner-video').srcObject=scannerStream;const detector=new BarcodeDetector({formats:['ean_13','ean_8','code_128','code_39','upc_a','upc_e','qr_code']});scannerTimer=setInterval(async()=>{try{const codes=await detector.detect($('scanner-video'));if(!codes.length)return;const value=codes[0].rawValue;$('search').value=value;filter();const card=[...document.querySelectorAll('.product')].find(row=>row.dataset.barcode===value||row.dataset.code===value);stopScanner();if(card)card.click();else alert('Produk dengan barcode '+value+' belum terdaftar.')}catch(error){}},350);$('scanner-status').textContent='Kamera aktif. Arahkan ke barcode produk.'}catch(error){stopScanner();alert('Kamera tidak dapat digunakan. Periksa izin kamera pada browser.')}}
$('scan-barcode').onclick=startScanner;$('scanner-close').onclick=stopScanner;
</script>
</body>
</html>
